'use strict';
const lessons=[
{id:'phishing',icon:'✉',title:'Phishing: look before you click',time:4,category:'Everyday essentials',summary:'Spot the small details behind convincing messages.',body:[['A message is a request for your trust','Phishing messages pretend to come from someone you know, a university, a bank, or a service. They try to get you to open a link, reveal information, transfer money, or install software. A familiar logo or name is easy to copy.'],['Pause when a message creates pressure','Urgent deadlines, threats to close your account, and unexpected prizes can make you skip checks. Read the full sender address and destination. A shortened link hides the destination. A padlock means an encrypted connection, not that the organisation is genuine.'],['Verify through a separate channel','Open the official app or type a known website address yourself. For a bursary, contact your university through an established channel. Ask the person who shared the message where it came from. Never give a portal password or one-time code to an applicant or caller.']],quiz:[['A bursary message asks for your portal password. What should you do?',['Send it before the deadline','Verify the opportunity using an official university channel','Trust it because a classmate forwarded it'],1,'Verify independently. A forwarded message does not establish who created it.'],['What does a website padlock establish?',['The connection is encrypted','The offer is genuine','The university approved the page'],0,'HTTPS protects transport. A scam website can also use HTTPS.'],['Which detail deserves extra checking?',['A message in your class group','An unexpected payment request with an urgent deadline','Both of these'],2,'The context and request both matter. Verify unusual requests even in familiar groups.']]},
{id:'passwords',icon:'⌘',title:'Stronger passwords, fewer worries',time:3,category:'Account security',summary:'Build unique passwords and add another layer of protection.',body:[['One account, one password','Password reuse lets one breached service put your other accounts at risk. Use a unique, long password or passphrase for each account. A password manager can generate and store these for you.'],['Turn on multi-factor authentication','Where available, add a passkey or authenticator app. Keep recovery codes somewhere secure and separate from your device. Never approve an unexpected sign-in request.'],['Keep your recovery route safe','Protect the email address used for password resets. Keep recovery details current and lock your phone. Do not share passwords or verification codes, even with someone claiming to provide support.']],quiz:[['Why is password reuse risky?',['A breach can expose your other accounts','It makes typing slower','It changes your username'],0,'Attackers can try exposed credentials on other services.'],['An unexpected MFA prompt appears. What next?',['Approve it','Reject it and check account activity through the official service','Share the code'],1,'An unexpected prompt can indicate an attempted sign-in.'],['Where should you enter your real password during a training challenge?',['A practice login page','A class group','Nowhere in the challenge'],2,'Training should never need your real account password.']]},
{id:'mobilemoney',icon:'↗',title:'Mobile money without the guesswork',time:4,category:'Everyday essentials',summary:'Check payment requests, reversals, and verification codes.',body:[['Check inside the official service','An SMS or screenshot alone is not a reliable payment confirmation. Confirm the transaction in your own official account or transaction history before releasing goods or sending a refund.'],['Protect your PIN and one-time codes','A caller can pretend to be support or a friend. Never reveal your mobile money PIN or one-time code. End the call and use the official provider support route if you are unsure.'],['Handle mistaken transfers carefully','Do not rush to send money back to a different number. Verify the transaction and follow your provider’s official reversal process. Keep the transaction reference and avoid publishing personal details.']],quiz:[['A screenshot says a customer paid you. What next?',['Release the item immediately','Check your own official transaction history','Send your PIN'],1,'Confirm the credit in your own account.'],['Someone claiming to be support needs your PIN.',['Share only half','Refuse and verify through official support','Send it privately'],1,'Your PIN should stay secret.'],['An unknown caller demands a reversal.',['Verify the payment and use the official process','Transfer to any number they give','Ignore account history'],0,'Verify first and follow your provider’s process.']]},
{id:'links',icon:'⌁',title:'Links, QR codes & downloads',time:3,category:'Digital habits',summary:'Know where a link takes you before you follow it.',body:[['Inspect the destination','Look for lookalike spellings and misleading subdomains. In campus.example.attacker.example, the ending domain is attacker.example. A university name somewhere in a URL does not make it official.'],['Treat QR codes like links','QR codes can hide destinations or cover a genuine poster’s code. Preview the URL and verify the source before opening it. A QR code is not proof of authenticity.'],['Use trusted download sources','Install software from official sources. Avoid unexpected executable attachments and requests to disable protections. Keep your browser and operating system updated.']],quiz:[['A campus poster has a QR code. Is it automatically safe?',['Yes','No, inspect and verify the destination','Only if printed in colour'],1,'QR codes are simply another way to deliver a link.'],['Which makes an unexpected download safer?',['Disabling antivirus','Verifying the source independently','Trusting its filename'],1,'Names and icons can be copied.'],['A university name appears in a URL. What does that prove?',['The university owns it','Nothing by itself','It must be encrypted'],1,'Read the actual domain and verify it independently.']]},
{id:'recovery',icon:'⚑',title:'Clicked something suspicious?',time:4,category:'Account security',summary:'Take useful next steps without panic.',body:[['Stop and preserve the evidence','Stop interacting with the suspicious message. Note what you clicked, downloaded, or entered. Save the sender, time, and relevant screenshots without sharing passwords or private codes.'],['Protect affected accounts','If you entered credentials, open the official service on a trusted device and change the password. Replace reused passwords, review active sessions, and enable MFA. Contact your bank or mobile money provider quickly if payments are involved.'],['Get appropriate help','Use your institution’s known IT support route. If you installed suspicious software, disconnect the affected device from networks and seek technical help. Report the message through the service where you received it.']],quiz:[['You entered a portal password on a suspicious page.',['Wait a week','Use the official service to change it and review sessions','Reply with another password'],1,'Act promptly through a trusted route and replace reused passwords too.'],['Should you include a password in a report?',['Yes','No','Only if support asks'],1,'Describe what happened without exposing secrets.'],['A suspicious payment has occurred.',['Contact the provider through official support promptly','Send more money','Post your PIN publicly'],0,'Act quickly through a known provider channel.']]},
{id:'privacy',icon:'◉',title:'A smaller digital footprint',time:3,category:'Digital habits',summary:'Share less sensitive information and stay in control.',body:[['Share with a purpose','Student cards, identity documents, receipts, and screenshots can reveal information useful to scammers. Share only what the recipient needs and confirm who they are.'],['Review app permissions','Check which apps can access your location, contacts, camera, and files. Remove access you no longer need. Install updates and lock devices when unattended.'],['Be careful on shared devices','Avoid saving passwords on shared computers. Sign out and check that your session has ended. Private browsing does not make a compromised device safe.']],quiz:[['What should you check before sharing an ID document?',['Who needs it and why','Whether the request has emojis','Only the file size'],0,'Verify the recipient and minimise what you share.'],['Does private browsing make a compromised computer safe?',['Yes','No','Only on campus'],1,'Private browsing mainly limits local browsing history.'],['What is a useful privacy habit?',['Give every app all permissions','Review permissions and remove unneeded access','Share recovery codes'],1,'Limit access to what each app needs.']]}
];
const scenarios=[
{title:'The bursary deadline',channel:'WhatsApp · forwarded message',sender:'Campus Bursary Desk',subject:'LAST CHANCE: student funding',text:'Congratulations! You have been shortlisted for a K8,500 bursary. Apply in the next 30 minutes. Enter your student portal password and pay K150 to reserve your place.\n\nhttps://unilus-funding.example/apply',scam:true,flags:['Requests your portal password','Uses urgency and a payment demand','An unverified lookalike funding domain'],reason:'Verify funding through an official university channel. Do not share credentials or pay an unverified applicant.'},
{title:'Library hours update',channel:'Student portal · announcement',sender:'Library notice board',subject:'Extended study hours',text:'The library has posted revised opening hours on the student portal. Open the portal using your usual bookmark and check the library notice board. No payment or account details are requested.',scam:false,flags:['Directs you to your own known bookmark','Requests no secrets or payment'],reason:'There are no obvious phishing indicators in this example. Using your established portal bookmark is a sensible way to verify the announcement.'},
{title:'The unexpected reversal',channel:'SMS · unknown sender',sender:'Unknown number',subject:'Please send my money back now',text:'I sent you K600 by mistake. I am at the hospital! Refund it to this different number immediately. Do not check the app because it is delayed. Send your PIN so I can confirm.',scam:true,flags:['Demands a PIN','Discourages checking your own account','Requests a refund to a different number'],reason:'Check your official transaction history and contact provider support through a known route. Follow the official reversal process.'},
{title:'Account suspension warning',channel:'Email · training example',sender:'IT Helpdesk <support@campus-security.example>',subject:'Your portal closes in 15 minutes',text:'Your student account has been flagged. Reply with your password and verification code to prevent deletion. This is confidential. Do not contact your faculty.',scam:true,flags:['Asks for a password and verification code','Threatens immediate deletion','Discourages independent verification'],reason:'Do not reply with secrets. Use your institution’s established support route.'},
{title:'A classmate shares a resource',channel:'Class WhatsApp group',sender:'Course representative',subject:'Python lecture notes',text:'Today’s lecture notes are in our usual course folder. Open the learning platform through the address you already use and look under Unit 7. Please ask the lecturer if you cannot find them.',scam:false,flags:['Uses an established platform','Encourages verification with the lecturer'],reason:'This example avoids an unfamiliar link or request for private information. Check through your normal learning platform.'},
{title:'Internship offer',channel:'Email · training example',sender:'Recruitment <careers@fastjobs.example>',subject:'You are hired without an interview',text:'You have secured an internship. Download OfferLetter.exe and disable your antivirus if it blocks the file. Pay the K200 processing fee today to receive your contract.',scam:true,flags:['Executable attachment disguised as a letter','Asks you to disable protection','Unexpected fee and urgency'],reason:'Verify the employer and role independently. Do not run unexpected executables or disable protections.'},
{title:'Someone needs your code',channel:'Messaging app',sender:'Friend’s account',subject:'Quick favour',text:'I accidentally sent my six-digit login code to your number. Please forward it quickly. I cannot call you right now. Do not worry about the warning in the message.',scam:true,flags:['Requests a login code','May be an impersonated or compromised account','Tells you to ignore a security warning'],reason:'Do not share codes. Contact your friend through another established route.'},
{title:'A password reset you requested',channel:'Official app',sender:'Account security settings',subject:'Reset request',text:'You opened your usual official app and selected “Forgot password”. The app asks you to use its normal recovery process. Keep any verification code private and enter it only in the official flow you initiated.',scam:false,flags:['You initiated the recovery','Uses the official app','Codes remain private'],reason:'An expected recovery flow in the official app is different from sending codes to a caller. Continue only within the genuine service.'}
];
const KEY='cyber-hygiene-v1';
let currentAccount=null,selectedLogin='',authBusy=false;
const profileKey=()=>currentAccount?'cyber-hygiene-profile-'+currentAccount.id:KEY;
const risksKey=()=>currentAccount?'cyber-hygiene-risks-'+currentAccount.id:'cyber-hygiene-risks';
let state={name:'Alex',completed:{},attempts:[],reports:[]},storageOK=true;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&typeof saved==='object'){state.name=typeof saved.name==='string'?saved.name.slice(0,40):'Alex';state.completed=saved.completed&&typeof saved.completed==='object'?saved.completed:{};state.attempts=Array.isArray(saved.attempts)?saved.attempts.filter(x=>x&&Number.isFinite(x.score)&&Number.isFinite(x.total)).slice(-100):[];state.reports=Array.isArray(saved.reports)?saved.reports.slice(-30):[]}}catch{storageOK=false}
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let quiz=null,challenge=null,filter='All',reportTab='issue';
function save(){try{localStorage.setItem(profileKey(),JSON.stringify(state))}catch{storageOK=false;toast('Browser storage unavailable. This session will not be saved.')}profile()}
function loadWorkspace(account){globalThis.CyberVaultUI?.detach();currentAccount=account;quiz=challenge=null;state={name:account?.name||'Guest',completed:{},attempts:[],reports:[]};try{const v=JSON.parse(localStorage.getItem(profileKey())||'null');if(v&&typeof v==='object'){state.name=typeof v.name==='string'?v.name.slice(0,40):state.name;state.completed=v.completed&&typeof v.completed==='object'?v.completed:{};state.attempts=Array.isArray(v.attempts)?v.attempts.filter(x=>x&&Number.isFinite(x.score)&&Number.isFinite(x.total)).slice(-100):[];state.reports=Array.isArray(v.reports)?v.reports.slice(-30):[]}}catch{storageOK=false}profile()}
function localAccounts(){try{return CyberAccounts.list()}catch{return []}}
function authShell(title,subtitle,content){return '<section class="figauth"><img class="authglow glowtop" src="assets/figma/signin-f7c4f.svg" alt="" aria-hidden="true"><img class="authglow glowbottom" src="assets/figma/signin-94679.svg" alt="" aria-hidden="true"><a class="authback" href="#home">← Explore the platform</a><div class="figauthhead"><h1>'+title+'</h1><a class="figwordmark" href="#home">Cyber Hygiene <img src="assets/figma/dashboard-0cfbd.svg" alt="" width="22" height="22"></a><p>'+subtitle+'</p></div><div class="figauthcard realaccountcard">'+content+'</div><div class="figauthor">OR</div><a class="figguest" href="#dashboard" data-guest>Continue as guest <span>↗</span></a><p class="deviceaccountnote">Device accounts only. No cross-device sync or email recovery.<br>Password Manager uses a separate master passphrase; use fictional vault entries for class.</p></section>'}
function authDestination(){const [,destination,action]=location.hash.slice(1).split('/');return destination==='password-manager'?'password-manager'+(action==='add'?'/add':''):'dashboard'}
function authLink(page){const destination=authDestination();return '#'+page+(destination==='dashboard'?'':'/'+destination)}
function signup(){return authShell('Create Your Account','Your learning journey starts here.','<h2>Add an account on this device</h2><form id="signupform" class="accountform"><label for="signup-name">Display name<input id="signup-name" name="name" maxlength="40" required autocomplete="nickname" placeholder="Your name"></label><label for="signup-login">Username<input id="signup-login" name="login" minlength="3" maxlength="40" required autocomplete="username" pattern="[A-Za-z0-9][A-Za-z0-9._-]{2,39}" placeholder="Choose a username"></label><label for="signup-password">Password<div class="passwordfield"><input id="signup-password" name="password" type="password" minlength="12" maxlength="128" required autocomplete="new-password" placeholder="At least 12 characters"><button type="button" data-togglepassword="signup-password" aria-label="Show password">Show</button></div></label><label for="signup-confirm">Confirm password<div class="passwordfield"><input id="signup-confirm" name="confirm" type="password" minlength="12" maxlength="128" required autocomplete="new-password" placeholder="Repeat your password"><button type="button" data-togglepassword="signup-confirm" aria-label="Show confirm password">Show</button></div></label><p class="passwordhint">Choose a new password for this prototype. Do not reuse a university, banking, or email password.</p><p class="autherror" id="autherror" role="alert"></p><button class="figlogin accountsubmit" type="submit">CREATE ACCOUNT</button></form><div class="figauthlinks"><p>Already have an account? <a href="'+authLink('signin')+'">Sign in</a></p></div>')}
async function submitAccount(form){if(authBusy)return;authBusy=true;const origin=location.hash,destination=authDestination(),errorBox=$('#autherror');const button=form.querySelector('[type="submit"]'),original=button.textContent;button.disabled=true;button.textContent=form.id==='signupform'?'Creating account…':'Signing in…';$('#autherror').textContent='';const f=new FormData(form);try{const account=form.id==='signupform'?await CyberAccounts.register({name:f.get('name'),login:f.get('login'),password:f.get('password'),confirm:f.get('confirm')}):await CyberAccounts.authenticate({login:f.get('login'),password:f.get('password')});if(location.hash!==origin)return;form.reset();loadWorkspace(account);save();location.hash=destination;render();toast('Welcome, '+state.name+'.');}catch(err){if(errorBox.isConnected)errorBox.textContent=err.message||'Unable to sign in. Please try again.';}finally{authBusy=false;if(button.isConnected){button.disabled=false;button.textContent=original;}}}
function profile(){$('#profilename').innerHTML=esc(state.name)+'<small>Student workspace</small>';$('#avatar').textContent=state.name.charAt(0).toUpperCase()}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500)}
function modal(html){$('#modalbody').innerHTML=html;$('#modal').showModal()}
$('.modalclose').onclick=()=>$('#modal').close();
$('#aboutbtn').onclick=()=>modal('<p class="eyebrow">CYBER HYGIENE</p><h2>A safer campus starts with small habits</h2><p>A working classroom demo with six lessons, quizzes, eight phishing scenarios, response guidance, and personal progress.</p><p>Your profile, results, and practice reports stay in this browser. Device-local accounts support password sign-in. There is no shared account server or university reporting backend. Practice reports are not sent to anyone. Use a unique prototype password. Do not enter banking credentials, PINs, or sensitive incident details.</p><p>All scenario domains ending in .example are fictional and cannot be used as real applications.</p><p>Password Manager is an encrypted, browser-local prototype with a separate master passphrase. Cloud sync, autofill, biometrics, one-time codes and recovery are outside this version. Use fictional entries for class.</p><p><a class="textlink" href="https://github.com/josephchitalu2/josephchitalu2.github.io/blob/main/cyber-hygiene/UML-ALIGNMENT.md" target="_blank" rel="noopener noreferrer">UML alignment and presentation scope ↗</a></p>');
const done=()=>lessons.filter(l=>state.completed[l.id]).length;
const accuracy=()=>{const a=state.attempts.reduce((r,x)=>[r[0]+x.score,r[1]+x.total],[0,0]);return a[1]?Math.round(a[0]/a[1]*100):null};
const intro=(tag,title,sub)=>'<div class="intro"><p class="eyebrow">'+tag+'</p><h1>'+title+'</h1><p class="muted">'+sub+'</p></div>';
const button=(text,action,secondary=false)=>'<button class="btn'+(secondary?' secondary':'')+'" '+action+'>'+text+'</button>';
function stats(){return '<div class="stats"><div class="stat"><span class="icon">▤</span><div><strong>'+done()+'<span class="muted" style="font-size:14px"> / 6</span></strong><small>Lessons completed</small></div></div><div class="stat"><span class="icon">◎</span><div><strong>'+(accuracy()===null?'—':accuracy()+'%')+'</strong><small>Overall practice accuracy</small></div></div><div class="stat"><span class="icon">✦</span><div><strong>'+state.attempts.filter(a=>a.type==='challenge').length+'</strong><small>Challenge rounds finished</small></div></div></div>'}
function lessonrow(l){return '<a class="lessonrow" href="#lesson/'+l.id+'"><div class="lessonicon">'+l.icon+'</div><div><h3>'+l.title+'</h3><div class="meta">'+l.time+' min · '+l.category+'<span class="tag">'+(state.completed[l.id]?'✓ COMPLETED':'QUICK LESSON')+'</span></div></div><span class="go">↗</span></a>'}
function signin(){const a=localAccounts();return authShell('Welcome Back','Sign in to your learning space.','<div class="accountpicker">'+(a.length?'<label for="saved-account">Accounts on this device<select id="saved-account"><option value="">Choose an account</option>'+a.map(x=>'<option value="'+esc(x.username)+'" '+(selectedLogin===x.username?'selected':'')+'>'+esc(x.name)+' (@'+esc(x.username)+')</option>').join('')+'</select></label>':'<p class="emptyaccounts">Your first time here? Create an account to keep your own learning progress.</p>')+'<a class="addaccount" href="'+authLink('signup')+'">＋ Create Cyber Hygiene profile</a></div><form id="signinform" class="accountform"><label for="signin-login">Username<input id="signin-login" name="login" maxlength="40" required autocomplete="username" placeholder="Your username" value="'+esc(selectedLogin)+'"></label><label for="signin-password">Password<div class="passwordfield"><input id="signin-password" name="password" type="password" maxlength="128" required autocomplete="current-password" placeholder="Enter your password"><button type="button" data-togglepassword="signin-password" aria-label="Show password">Show</button></div></label><p class="autherror" id="autherror" role="alert"></p><button class="figlogin accountsubmit" type="submit">SIGN IN</button></form><div class="figauthlinks"><p>Forgot your password? <button class="textbtn" data-authhelp>View options</button></p><p>Don’t have an account? <a href="'+authLink('signup')+'">Sign up</a></p></div><p class="figauthnote">Create a separate password for this prototype. Your account stays in this browser.</p>')}
function landing(){return `
<div class="landingpage">
<header class="landingnav"><a class="brand" href="#home" aria-label="Cyber Hygiene home"><span class="brandmark">C<span>✦</span></span><span>cyber<span class="mint">hygiene</span><small>BUILD SAFER HABITS</small></span></a><nav aria-label="Website navigation"><a href="#training">Explore lessons</a><a href="#report">Get help</a></nav><a class="btn secondary small" href="#signin">Sign in ↗</a></header>
<section class="landinghero">
<div class="landingcopy"><p class="eyebrow"><span class="live"></span> CYBER AWARENESS FOR STUDENT LIFE</p><h1>Big opportunities.<br>Small red flags.<br><span class="mint">Know the difference.</span></h1><p class="landingdescription">That bursary link. That urgent payment. That message from a friend. Learn to spot the scam before it becomes your story.</p><div class="landingactions"><a class="btn" href="#lesson/phishing">Start learning <span>↗</span></a><a class="btn secondary" href="#challenge">Try a challenge <span>◎</span></a></div><p class="landingpromise">Free to explore <span>·</span> No sign-up needed <span>·</span> Short, practical lessons</p></div>
<div class="previewscene"><div class="previewglow" aria-hidden="true"></div><div class="messagepreview"><div class="previewtoolbar"><span class="previewdot"></span><span class="previewdot"></span><span class="previewdot"></span><span>THE MESSAGE THAT ALMOST LOOKS RIGHT</span></div><div class="previewchat"><div class="senderavatar">B</div><div><strong>Campus Bursary Desk</strong><small>Forwarded message · Training example</small></div><span class="previewtime">now</span></div><div class="previewbubble"><p>Good news! You've been shortlisted for a <strong>K8,500 student bursary.</strong> 🎓</p><p>Confirm within <span class="redflag">30 minutes</span>. Enter your <span class="redflag">student portal password</span> and pay a <span class="redflag">K150 processing fee</span>.</p><span class="previewurl">unilus-funding.example/apply</span></div><div id="landingfeedback"><p class="previewquestion">Would you trust this message?</p><button class="btn previewbutton" data-preview-scam>Show me the warning signs <span>↗</span></button></div><p class="previewdisclaimer">Fictional example. The address is not a live link.</p></div><div class="previewcaption"><span>✦</span> One pause can make all the difference.</div></div>
</section>
<div class="landingfacts"><div><strong>06</strong><span>short lessons<br>for everyday situations</span></div><div><strong>08</strong><span>realistic scenarios<br>to test your judgement</span></div><div><strong>03–04</strong><span>minutes per lesson<br>at your own pace</span></div></div>
<section class="landingpath"><div><p class="eyebrow">FROM AWARENESS TO ACTION</p><h2>Build a habit.<br>Carry it everywhere.</h2><p class="muted">Start with what matters to you. Every lesson ends with a quick check and a clear next step.</p><a class="textlink" href="#training">Explore the learning hub ↗</a></div><ol class="landingsteps"><li><span>01</span><div><h3>Learn what to look for</h3><p>Understand phishing, account security, mobile money scams, and safer digital habits.</p></div></li><li><span>02</span><div><h3>Practise with familiar situations</h3><p>Make a decision, get immediate feedback, and understand the warning signs.</p></div></li><li><span>03</span><div><h3>Know your next move</h3><p>Track your learning and find practical guidance when something feels wrong.</p></div></li></ol></section>
<section class="landingclose"><p class="eyebrow">YOUR NEXT SMALL WIN</p><h2>A few minutes today.<br>Better judgement tomorrow.</h2><a class="btn" href="#lesson/phishing">Take your first lesson ↗</a><p>Progress saves in this browser. We never ask for your real passwords or PINs.</p></section>
<footer class="landingfooter"><a class="brand" href="#home">cyber<span class="mint">hygiene</span></a><span>A student project for safer digital habits.</span><a href="#report">Report & respond ↗</a><button class="textbtn" data-about>About this demo</button></footer>
</div>`}

function dashboard(){const risks=readRisks(),latest=risks.at(-1),score=latest?latest.likelihood*latest.impact:null;return `
<div class="figdashboard"><div class="figgreeting"><p class="eyebrow">YOUR DIGITAL SAFETY</p><h1>Hey ${esc(state.name)},</h1><p>Are you confident with your digital safety?<br>Let’s find out...</p></div><div class="dashcolumns"><section class="dashrisk"><div class="row sectionhead"><h2>Risk Assessment Score</h2><a class="textlink" href="#risk">Tap here for details ↗</a></div><a class="figriskcard" href="#risk"><span>Overall Risk Score</span><strong>${score===null?'—':score}<small>/25</small></strong><b class="${score===null?'':riskClass(score)}">${score===null?'Start your assessment':riskLabel(score)}</b><p>${score===null?'Rate a risk to see your score.':'Based on your latest manual assessment.'}</p></a><div class="figactivity"><h2>Activity Tracker</h2><p class="muted">Your completed practice in this browser</p>${lessons.map(l=>{const n=state.attempts.filter(x=>x.lesson===l.id).length;return '<div class="activityline"><span>'+l.title.split(':')[0]+'</span><div><i style="width:'+Math.min(100,n*20)+'%"></i></div><b>'+n+'</b></div>'}).join('')}</div></section><section class="dashright"><div class="figalerts"><h2>Security Alerts</h2><div class="alertsbody"><p><span class="alertsymbol">!</span><span>Verify unexpected bursary and payment requests.</span></p><p><img src="assets/figma/dashboard-62b71.svg" alt="" width="21" height="18"><span>Review your account sessions using each official service.</span></p><p><span class="alertsymbol">✦</span><span>Use a unique password and enable MFA where available.</span></p><small>Awareness reminders · No live account monitoring</small></div></div><div class="figquick"><h2>Your next step</h2><a href="#verify">Check a suspicious message <span>↗</span></a><a href="#training">Cyber Training Awareness <span>↗</span></a><a href="#password-manager">Open Password Manager <span>↗</span></a><a href="#guidelines">What to do after an incident <span>↗</span></a><a href="#challenge">Try a cyber awareness challenge <span>↗</span></a><a href="#report">Report a problem <span>↗</span></a></div></section></div>${stats()}<div class="figbrandfooter"><em>Cyber Hygiene Platform</em><p>Improve security with awareness</p><button class="textbtn" data-about>About & privacy</button></div></div>`}
function readRisks(){try{const r=JSON.parse(localStorage.getItem(risksKey())||'[]');return Array.isArray(r)?r.filter(x=>x&&typeof x.title==='string'&&Number.isInteger(x.likelihood)&&x.likelihood>=1&&x.likelihood<=5&&Number.isInteger(x.impact)&&x.impact>=1&&x.impact<=5).slice(-30):[]}catch{return []}}
function riskLabel(n){return n>=15?'High Risk':n>=6?'Medium Risk':'Low Risk'}
function riskClass(n){return n>=15?'riskhigh':n>=6?'riskmedium':'risklow'}
function riskview(){const r=readRisks(),last=r.at(-1),n=last?last.likelihood*last.impact:null;return '<div class="reading">'+intro('MANUAL ASSESSMENT','Risk Assessment Score','Rate likelihood and impact to prioritise a security concern.')+'<div class="figriskcard riskwide"><span>Overall Risk Score</span><strong>'+(n===null?'—':n)+'<small>/25</small></strong><b>'+(n===null?'No assessment yet':riskLabel(n))+'</b></div><section class="mintpanel"><h2>1. Risk Assessment Score</h2><form id="riskform"><label>Risk or concern<input name="title" maxlength="120" required placeholder="Example: Reusing a student portal password"></label><div class="riskfields"><label>Likelihood (1–5)<select name="likelihood">'+[1,2,3,4,5].map(n=>'<option '+(n===3?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label>Impact (1–5)<select name="impact">'+[1,2,3,4,5].map(n=>'<option '+(n===3?'selected':'')+'>'+n+'</option>').join('')+'</select></label></div><p class="calculated" id="riskcalc" aria-live="polite">Calculated inherent rating: 9 (Medium Risk)</p><button class="btn" type="submit">Log Risk Vector to Registry</button></form></section><section class="mintpanel"><h2>2. Active Hazard Density Matrix</h2><img class="riskmatrix" src="assets/figma/risk-c78d7.png" alt="Reference 5 by 5 risk matrix showing increasing risk from low to high. Use likelihood times impact to calculate your score."><p>Reference matrix from the original design. Your logged score uses likelihood × impact, from 1 to 25.</p></section><section class="mintpanel"><h2>3. Master Threat Log</h2>'+(r.length?r.slice().reverse().map(x=>'<div class="risklog"><div><strong>'+esc(x.title)+'</strong><small>Likelihood: '+x.likelihood+' · Impact: '+x.impact+'</small></div><b class="'+riskClass(x.likelihood*x.impact)+'">'+riskLabel(x.likelihood*x.impact)+'</b></div>').join(''):'<p>No risks logged yet. Add your first assessment above.</p>')+'</section><p class="muted">Manual planning tool. This score does not measure live device or account security.</p></div>'}
function analyseMessage(text){const findings=[];if(/password|passcode|pin\b|one.time|otp|verification code/i.test(text))findings.push('A request involving credentials or verification codes needs independent checking. Never share these with a caller or sender.');if(/urgent|immediately|last chance|minutes|suspend|delete your|act now/i.test(text))findings.push('Urgent language or threats may pressure you into skipping checks.');if(/processing fee|pay.*fee|reserve your|refund|send.*money|transfer.*now/i.test(text))findings.push('A payment or refund request deserves verification through an official channel.');if(/disable.*antivirus|\.exe\b|\.scr\b/i.test(text))findings.push('An executable download or request to disable protection is a warning sign.');if(/https?:\/\/[^\s]+/i.test(text))findings.push('A link is present. Inspect its actual destination and open the official service independently. This tool does not visit links.');return findings}
function verifyview(){return '<div class="reading">'+intro('CHECK BEFORE YOU CLICK','Verification','Check an email, link or message before you respond.')+'<section class="mintpanel verifycard"><h2>Check an email, link or message<br>before you click or respond.</h2><h3>How it works</h3><ol><li><strong>Copy</strong><br>Use a redacted or fictional message. Remove personal information and credentials.</li><li><strong>Paste</strong><br>Paste it into the box below.</li><li><strong>Check</strong><br>Look for common warning signs and useful next steps.</li></ol><form id="verifyform"><label>Paste your link, email or message here<textarea name="content" maxlength="5000" minlength="5" required placeholder="Paste content here..."></textarea></label><button class="btn" type="submit">Verify Now</button><button class="textbtn" type="reset" data-clearverify>Clear content</button></form><p class="toolnote">Local educational checks only. No live scan, malware analysis or guarantee that a message is safe.</p><div id="verifyresult" aria-live="polite"></div></section></div>'}
function learning(){return intro('CYBER TRAINING AWARENESS','Learn it. Practise it. Remember it.','Your learning hub, lesson quizzes and phishing challenges in one place.')+'<section class="feature training-banner"><h2>Spot the scam</h2><p>Practise with eight fictional messages, including fake bursaries and portal password requests. Get an explanation after every answer.</p><a class="btn" href="#challenge">Start phishing challenge ↗</a></section><h2>Learning hub &amp; knowledge checks</h2><p class="muted">Each short lesson ends with its own three-question quiz.</p>'+'<div class="chips">'+['All','Everyday essentials','Account security','Digital habits'].map(f=>'<button class="chip '+(filter===f?'active':'')+'" data-filter="'+f+'">'+f+'</button>').join('')+'</div><div class="grid">'+lessons.filter(l=>filter==='All'||l.category===filter).map(l=>'<article class="lessoncard"><div class="lessonicon">'+l.icon+'</div><span class="meta">'+l.time+' MIN · '+l.category.toUpperCase()+'</span><h2 style="margin-top:12px">'+l.title+'</h2><p>'+l.summary+'</p><a class="btn '+(state.completed[l.id]?'secondary':'')+'" href="#lesson/'+l.id+'">'+(state.completed[l.id]?'Review lesson ✓':'Open lesson ↗')+'</a></article>').join('')+'</div>'}
function lesson(id){const l=lessons.find(l=>l.id===id);if(!l)return missing();return '<div class="reading"><a class="back" href="#training">← Cyber Training Awareness</a>'+intro(l.category.toUpperCase(),l.title,l.time+' minute read · 3 question knowledge check')+'<article class="figlesson">'+l.body.map(([h,p])=>'<section class="mintpanel"><h2>'+h+'</h2><p>'+p+'</p></section>').join('')+'</article><section class="feature"><h2>Ready to check your understanding?</h2><p>Complete three questions. You can retry and learn from every answer.</p>'+button('Start knowledge check ↗','data-quiz="'+l.id+'"')+'</section></div>'}
function startquiz(id){quiz={id,index:0,score:0,selected:null,revealed:false};location.hash='quiz/'+id;render()}
function quizview(id){if(!quiz||quiz.id!==id)return '<div class="reading">'+intro('KNOWLEDGE CHECK','Ready when you are.','Your lesson is still available to review.')+button('Begin quiz','data-quiz="'+esc(id)+'"')+'</div>';const l=lessons.find(l=>l.id===id);if(!l)return missing();if(quiz.index>=l.quiz.length)return resultview('quiz',quiz.score,3,l.id);const q=l.quiz[quiz.index];return '<div class="reading"><a class="back" href="#lesson/'+l.id+'">← Review lesson</a>'+intro('QUESTION '+(quiz.index+1)+' OF 3',q[0],l.title)+'<div class="article">'+q[1].map((o,i)=>'<button class="quizoption '+(quiz.selected===i?'selected':'')+'" data-answer="'+i+'" '+(quiz.revealed?'disabled':'')+'>'+String.fromCharCode(65+i)+'. '+o+'</button>').join('')+(quiz.revealed?'<div class="feedback '+(quiz.selected===q[2]?'':'bad')+'"><strong>'+(quiz.selected===q[2]?'That’s right.':'A useful thing to remember.')+'</strong><br>'+q[3]+'</div>'+button(quiz.index===2?'See my results':'Next question ↗','data-nextquiz'):button('Check answer','data-checkquiz '+(quiz.selected===null?'disabled':'')))+'</div></div>'}
function resultview(type,score,total,id){return '<div class="reading">'+intro('PRACTICE COMPLETE','Every check builds a better habit.','Your result has been added to your progress.')+'<div class="article"><div class="resultnumber">'+score+' / '+total+'</div><h2>'+(score===total?'Great judgement. Keep practising.':'Good practice. Keep building your awareness.')+'</h2><p>'+(type==='quiz'?(score>=2?'You passed this lesson.':'Review the lesson and try again. Two correct answers complete it.'):'Review the explanations and keep verifying unusual requests through a trusted channel.')+'</p><div class="row">'+button('Try again',type==='quiz'?'data-quiz="'+id+'"':'data-startchallenge',true)+'<a class="btn" href="#progress">View my progress ↗</a></div></div></div>'}
function challengeview(){if(!challenge)return intro('SPOT THE SCAM','Looks familiar. Is it trustworthy?','Test your judgement with realistic student situations.')+'<div class="twocol"><div class="article"><div class="lessonicon">◎</div><h2 style="font-size:27px;margin-top:22px">Eight messages. One useful habit.</h2><p>Read each example, decide whether it has scam indicators, and learn why. Some messages are legitimate. You do not need to open any links or enter any credentials.</p><p>About 5 minutes · Immediate feedback · Retry anytime</p>'+button('Start challenge ↗','data-startchallenge')+'</div><div class="feature"><h2>A quick check</h2><ol class="checklist"><li>Who is really asking?</li><li>What do they want you to do?</li><li>Can you verify it another way?</li></ol><p>These are fictional training examples. They are never live applications or payment requests.</p></div></div>';if(challenge.index>=scenarios.length)return resultview('challenge',challenge.score,scenarios.length);const s=scenarios[challenge.index];return '<div class="reading">'+intro('SCENARIO '+(challenge.index+1)+' OF '+scenarios.length,s.title,s.channel)+'<article class="message"><div class="messagehead">From: '+s.sender+'<br><strong>'+s.subject+'</strong></div><div class="messagebody">'+esc(s.text)+'</div></article>'+(challenge.revealed?'<div class="feedback '+(challenge.selected===s.scam?'':'bad')+'"><strong>'+(challenge.selected===s.scam?'Good judgement.':'Let’s look more closely.')+' '+(s.scam?'This has scam indicators.':'No obvious scam indicators in this example.')+'</strong><ul>'+s.flags.map(f=>'<li>'+f+'</li>').join('')+'</ul>'+s.reason+'</div>'+button(challenge.index===7?'See my results':'Next scenario ↗','data-nextchallenge'):'<div class="row">'+button('Suspicious message','data-verdict="scam"')+button('No obvious scam indicators','data-verdict="safe"',true))+'</div>'}
function reportview(){const options=['Phishing / Scam','Account Hacked','Identity Theft','Online Harassment','Malware / Virus','Data Breach','Other'];return '<div class="reading">'+intro('CYBER HYGIENE','Report Manager','Get clear next steps and practise reporting a problem.')+'<div class="reporttabs"><button class="chip '+(reportTab==='issue'?'active':'')+'" data-reporttab="issue">Issue</button><button class="chip '+(reportTab==='status'?'active':'')+'" data-reporttab="status">Status</button></div>'+(reportTab==='issue'?'<section class="mintpanel reportpanel"><h2>Select the issue you are facing</h2><form id="reportform"><label>Where did it happen?<select name="channel"><option>WhatsApp</option><option>Email</option><option>SMS</option><option>Website</option><option>Other</option></select></label><label>Select the issue<select name="kind">'+options.map(x=>'<option>'+x+'</option>').join('')+'</select></label><label>Your problem isn’t listed? Tell us what happened below.<textarea name="details" minlength="10" maxlength="1500" required placeholder="Describe Your Problem. Use fictional or redacted details only."></textarea></label><button class="btn" type="submit">Save Demo Report</button></form><p class="toolnote">Practice only. Saved in this browser, not submitted to university support. Do not include passwords, PINs, or personal details.</p></section><section class="feature"><h2>What to do now</h2><ol class="checklist"><li>Stop interacting with suspicious requests.</li><li>If credentials were exposed, change them through the official service and review active sessions.</li><li>Contact your institution’s known IT support route. For payments, contact your bank or mobile money provider promptly.</li><li>Keep evidence with sensitive information redacted. Disconnect a device from networks if you installed suspicious software and seek technical help.</li></ol></section>':'<section class="mintpanel"><h2>Your report history</h2>'+(state.reports.length?state.reports.slice().reverse().map(x=>'<article class="reportentry"><div class="row"><h3>'+esc(x.kind)+'</h3><span>Saved locally</span></div><p>'+esc(x.details)+'</p><small>'+esc(x.channel)+' · '+esc(new Date(x.date).toLocaleDateString())+'</small></article>').join(''):'<p>No practice reports saved yet.</p>')+'<button class="btn" data-export="reports">Export practice reports</button><p class="toolnote">There is no central review queue or email feedback in this demo.</p></section>')+'</div>'}
function progressview(){return intro('MY PROGRESS','Small steps add up.','Review what you’ve learned and where to go next.')+stats()+'<section class="article"><div class="row"><div><h2>Your learning journey</h2><p>'+done()+' of 6 lessons passed · Two correct answers pass each lesson</p></div>'+button('Export progress','data-export="progress"',true)+'</div><div class="progressbar"><span style="width:'+done()/6*100+'%"></span></div><div class="tablewrap"><table><thead><tr><th>Lesson</th><th>Status</th><th>Best score</th><th></th></tr></thead><tbody>'+lessons.map(l=>{const a=state.attempts.filter(x=>x.lesson===l.id);return '<tr><td>'+l.title+'</td><td>'+(state.completed[l.id]?'✓ Passed':'To explore')+'</td><td>'+(a.length?Math.max(...a.map(x=>x.score))+' / 3':'—')+'</td><td><a class="textlink" href="#lesson/'+l.id+'">Open ↗</a></td></tr>'}).join('')+'</tbody></table></div></section><h2 style="margin:28px 0 15px">Recent practice</h2>'+(state.attempts.length?'<div class="tablewrap"><table><thead><tr><th>Activity</th><th>Result</th><th>Date</th></tr></thead><tbody>'+state.attempts.slice(-8).reverse().map(a=>'<tr><td>'+esc(a.title)+'</td><td>'+a.score+' / '+a.total+'</td><td>'+esc(new Date(a.date).toLocaleDateString())+'</td></tr>').join('')+'</tbody></table></div>':'<div class="empty">Your first practice result will appear here.<br><a class="textlink" href="#training">Explore a lesson ↗</a></div>')}
function accountview(){return '<div class="reading accountpage"><div class="accountbanner"><span class="accountavatar">'+esc(state.name.charAt(0).toUpperCase())+'</span><div><h1>'+esc(state.name)+'</h1><p>Personal Information</p></div></div><div class="accountmenu"><a href="#profile"><span>♙</span>Personal Information<b>›</b></a><button data-privacy><span>◇</span>Security & Privacy<b>›</b></button><button data-notifications><span>♧</span>Notification<b>›</b></button><button data-about><span>?</span>Help & Support<b>›</b></button></div><section class="article"><h2>Password storage</h2><p>Keep the logins you save in your encrypted Password Manager.</p><div class="row"><a class="btn" href="#password-manager">View saved passwords</a><a class="btn secondary" href="#password-manager/add">＋ Add account</a></div></section><div class="switchaccount"><a href="#signin" data-switchaccount>Switch Cyber Hygiene profile</a><a href="#signup">＋ Create Cyber Hygiene profile</a></div><button class="btn accountlogout" data-logout>LOG OUT</button></div>'}
function profileview(){return '<div class="reading">'+intro('MY ACCOUNT','Your personal learning space.','Choose a display name and manage progress saved on this device.')+'<section class="article"><form id="profileform"><label>Display name<input name="name" value="'+esc(state.name)+'" maxlength="40" required autocomplete="nickname"></label><button class="btn" type="submit">Save profile</button></form><hr class="divider"><h2>Your privacy</h2><p>This demo supports local accounts and does not connect to student portals. Your display name, quiz results, and practice reports save in this browser. Clearing browser data can remove them.</p><p>Cross-device sync, shared accounts, and institutional reporting are future backend work.</p><div class="row">'+button('Export progress','data-export="progress"',true)+button('Reset demo data','data-reset',true)+'</div></section></div>'}
function missing(){return intro('PAGE NOT FOUND','Let’s get you back on track.','Choose a page from the menu.')+'<a class="btn" href="#dashboard">Back to overview</a>'}
function render(){const [page,id]=(location.hash.slice(1)||'signin').split('/');document.body.classList.toggle('landing-mode',page==='home'||page==='signin'||page==='signup');document.body.classList.toggle('auth-mode',['signin','signup'].includes(page));document.body.classList.toggle('navy-mode',['risk','account','profile'].includes(page));if(page!=='password-manager')globalThis.CyberVaultUI?.detach();const nav=['lesson','quiz','challenge','learn'].includes(page)?'training':page==='profile'?'account':page;document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===nav);if(a.dataset.nav===nav)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#main').innerHTML=({signin,signup,home:landing,dashboard,risk:riskview,verify:verifyview,learn:learning,training:learning,guidelines:()=>CyberGuidelines.render(),'password-manager':()=>'<div id="vault-root"></div>',lesson:()=>lesson(id),quiz:()=>quizview(id),challenge:challengeview,report:reportview,progress:progressview,account:accountview,profile:profileview}[page]||missing)();if(!storageOK)$('#main').insertAdjacentHTML('afterbegin','<div class="warning">Browser storage is unavailable. Progress will last only for this session.</div>');profile();if(page==='password-manager')CyberVaultUI.mount($('#vault-root'),currentAccount,id==='add')}
function record(a){state.attempts.push({...a,date:new Date().toISOString()});state.attempts=state.attempts.slice(-100);save()}
function download(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('change',e=>{if(e.target.id==='saved-account'){selectedLogin=e.target.value;$('#signin-login').value=selectedLogin;$('#signin-password').value='';$('#signin-password').focus();}});
document.addEventListener('click',e=>{if(e.target.closest('[data-closemodal]'))$('#modal').close();if(e.target.closest('[data-switchaccount]')){save();selectedLogin=currentAccount?.username||'';loadWorkspace(null);}const guest=e.target.closest('[data-guest]');if(guest){e.preventDefault();if(currentAccount)save();loadWorkspace(null);location.hash='dashboard';render();}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;
if(b.hasAttribute('data-closemodal'))$('#modal').close();
if(b.hasAttribute('data-togglepassword')){const input=document.getElementById(b.dataset.togglepassword);const show=input.type==='password';input.type=show?'text':'password';b.textContent=show?'Hide':'Show';b.setAttribute('aria-label',(show?'Hide':'Show')+' password');b.setAttribute('aria-pressed',String(show));}
if(b.hasAttribute('data-reporttab')){reportTab=b.dataset.reporttab;render();}
if(b.hasAttribute('data-privacy'))modal('<h2>Security & Privacy</h2><p>Your demo profile, learning results and practice reports save in this browser. Device-local password hashes are stored in this browser. Learning and reporting data are not encrypted. Verification runs locally and does not send message text to a server. Password Manager encrypts its separate vault with a master passphrase; account sign-in alone does not unlock it. The classroom vault has no recovery or sync; use fictional entries.</p><p>You can export your progress or reset the demo data from Personal Information. Cross-device accounts, email recovery and MFA require a backend.</p>');
if(b.hasAttribute('data-notifications'))modal('<h2>Notifications</h2><p>Awareness reminders appear on your dashboard. This demo does not send push, email or SMS notifications.</p><p>Use the learning hub and progress page to continue your practice at any time.</p>');
if(b.hasAttribute('data-authhelp'))modal('<h2>Account recovery</h2><p>These accounts exist only in this browser. There is no email password-reset service. Try your saved account username, continue as a guest, or create another account.</p><p>Clearing site data removes local accounts and progress. Keep your password somewhere you can retrieve it.</p><a class="btn" href="#signup" data-closemodal>Add another account</a>');
if(b.hasAttribute('data-newprofile'))location.hash='signup';
if(b.hasAttribute('data-logout')){save();loadWorkspace(null);selectedLogin='';location.hash='signin';render();toast('Signed out. Your profile remains saved on this device.');}
if(b.hasAttribute('data-clearverify'))$('#verifyresult').innerHTML='';
if(b.hasAttribute('data-about'))$('#aboutbtn').click();
if(b.hasAttribute('data-preview-scam')){$('#landingfeedback').innerHTML='<div class="feedback bad"><strong>Three reasons to pause.</strong><br>The deadline creates pressure. A portal password should stay private. An unverified processing fee needs independent checking.</div><a class="btn previewbutton" href="#challenge">Practise with more messages ↗</a>';}
if(b.hasAttribute('data-filter')){filter=b.dataset.filter;render()}
if(b.hasAttribute('data-quiz'))startquiz(b.dataset.quiz);
if(b.hasAttribute('data-answer')&&quiz&&!quiz.revealed){quiz.selected=Number(b.dataset.answer);render()}
if(b.hasAttribute('data-checkquiz')&&quiz&&quiz.selected!==null&&!quiz.revealed){const l=lessons.find(l=>l.id===quiz.id);quiz.revealed=true;if(quiz.selected===l.quiz[quiz.index][2])quiz.score++;render()}
if(b.hasAttribute('data-nextquiz')&&quiz&&quiz.revealed){quiz.index++;quiz.selected=null;quiz.revealed=false;if(quiz.index===3){if(quiz.score>=2)state.completed[quiz.id]=true;record({type:'quiz',lesson:quiz.id,title:lessons.find(l=>l.id===quiz.id).title,score:quiz.score,total:3})}render()}
if(b.hasAttribute('data-startchallenge')){challenge={index:0,score:0,revealed:false,selected:null};render()}
if(b.hasAttribute('data-verdict')&&challenge&&!challenge.revealed){challenge.selected=b.dataset.verdict==='scam';challenge.revealed=true;if(challenge.selected===scenarios[challenge.index].scam)challenge.score++;render()}
if(b.hasAttribute('data-nextchallenge')&&challenge&&challenge.revealed){challenge.index++;challenge.revealed=false;if(challenge.index===8)record({type:'challenge',title:'Spot the scam',score:challenge.score,total:8});render()}
if(b.hasAttribute('data-export')){const reports=b.dataset.export==='reports';download(reports?{practiceOnly:true,reports:state.reports}:{name:state.name,completed:state.completed,attempts:state.attempts},reports?'cyber-hygiene-practice-reports.json':'cyber-hygiene-progress.json');toast('Export downloaded.')}
if(b.hasAttribute('data-reset'))modal('<h2>Reset your demo workspace?</h2><p>This removes your saved name, results, and practice notes from this browser. You can export progress first.</p>'+button('Reset everything','data-confirmreset',true));
if(b.hasAttribute('data-confirmreset')){state={name:currentAccount?.name||'Guest',completed:{},attempts:[],reports:[]};quiz=challenge=null;try{localStorage.removeItem(risksKey())}catch{}save();$('#modal').close();location.hash='dashboard';render();toast('Demo workspace reset.')}
});
document.addEventListener('input',e=>{if(e.target.closest&&e.target.closest('#riskform')){const f=new FormData($('#riskform')),n=Number(f.get('likelihood'))*Number(f.get('impact'));$('#riskcalc').textContent='Calculated inherent rating: '+n+' ('+riskLabel(n)+')';}if(e.target.id==='signin-name')e.target.setCustomValidity('')});
document.addEventListener('submit',e=>{if(e.target.id==='riskform'){e.preventDefault();const f=new FormData(e.target),title=f.get('title').trim(),likelihood=Number(f.get('likelihood')),impact=Number(f.get('impact'));if(!title||![likelihood,impact].every(v=>Number.isInteger(v)&&v>=1&&v<=5))return;const r=readRisks();r.push({title:title.slice(0,120),likelihood,impact,date:new Date().toISOString()});try{localStorage.setItem(risksKey(),JSON.stringify(r.slice(-30)));render();toast('Risk logged in your local registry.')}catch{toast('Unable to save. Browser storage is unavailable.');}}
if(e.target.id==='verifyform'){e.preventDefault();const content=new FormData(e.target).get('content').trim();if(content.length<5)return;const f=analyseMessage(content);$('#verifyresult').innerHTML='<div class="verificationresult"><h3>'+(f.length?'Warning signs to review':'No common warning signs found')+'</h3>'+(f.length?'<ul>'+f.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'<p>This does not establish that the message is safe. Scams may avoid these patterns.</p>')+'<p>Verify unusual requests through an official channel you already know. Do not reply with passwords, PINs or codes.</p></div>';}
if(['signinform','signupform'].includes(e.target.id)){e.preventDefault();void submitAccount(e.target);}if(e.target.id==='profileform'){e.preventDefault();const n=new FormData(e.target).get('name').trim();if(!n)return;state.name=n.slice(0,40);save();toast('Profile saved.')}
if(e.target.id==='reportform'){e.preventDefault();const f=new FormData(e.target);state.reports.push({channel:f.get('channel'),kind:f.get('kind'),details:f.get('details').trim(),date:new Date().toISOString()});state.reports=state.reports.slice(-30);save();render();modal('<h2>Practice report saved</h2><p>Your note is saved in this browser. No report has been sent. For an actual incident, contact the appropriate official support channel.</p>'+button('Download practice notes','data-export="reports"'))}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
